import { Component, Directive } from '@angular/core';

@Directive({ inputs: ['order'] })
class PctAvatarBase {}

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '[tabindex]': 'order()',
  },
})
export class PctAvatar extends PctAvatarBase {
  protected order(): number {
    return 0;
  }
}
